148	        httpMetadata: { contentType: "application/x-ndjson" },
149	      });
150	
151	      return newLineBytes.byteLength;
152	    },
153	
154	    async finalize(handle) {
155	      if (handle.store !== "r2") {
156	        return { bytes: 0, compressed: false };
157	      }
158	      const baseKey = handle.logRef;
159	
160	      // Collect all shards and concatenate to compute total bytes and hash.
161	      const shardIdx = await highestShardIndex(bucket, baseKey, prefix);
162	      if (shardIdx < 0) {
